query FindZubat($where: pokemonspecies_bool_exp!, $pokemonWhere: pokemon_bool_exp!, $typeLimit: Int!, $pokemonLimit: Int!, $limit: Int!) {
  pokemonspecies(where: $where, limit: $limit) {
    id
    name
    evolution_chain_id
    pokemons(where: $pokemonWhere, limit: $pokemonLimit) {
      id
      name
      pokemontypes(limit: $typeLimit) { type { name } }
    }
  }
}

query ChainSpecies($where: pokemonspecies_bool_exp!, $pokemonWhere: pokemon_bool_exp!, $typeLimit: Int!, $pokemonLimit: Int!, $limit: Int!) {
