query ShedinjaAbility($where: pokemon_bool_exp!, $pokemonLimit: Int!, $abilityLimit: Int!, $flavorLimit: Int!, $language: String!) {
  pokemon(where: $where, limit: $pokemonLimit) {
    id
    name
    pokemonabilities(limit: $abilityLimit, order_by: {slot: asc}) {
      ability {
        id
        name
        abilityflavortexts(where: {language: {iso639: {_eq: $language}}}, limit: $flavorLimit, order_by: {version_group_id: desc}) {
          flavor_text
          language { iso639 }
        }
      }
      is_hidden
      slot
    }
  }
}

